j:jelly.script:
function configureRemoteTableFlow(referenceColumn) {
    var flowSysId = g_form.getValue(referenceColumn);
    var url = new GlideURL("/now/workflow-studio/builder");
    url.addParam("tableName", "sys_hub_flow");
    url.addParam("builderId", "flow");
    url.addParam("sysId", flowSysId ? flowSysId : "-1");

    var window = getTopWindow();
    window.open(url.getURL());
}
